            for (int j = 0; j < S; j++) sum += expf(logits[j] - mx);
            float inv = 1.f / sum;
            for (int d = 0; d < D; d++) {
                float acc = 0.f;
                for (int j = 0; j < S; j++) {
                    if (causal && j > i) continue;
                    float p = expf(logits[j] - mx) * inv;
                    acc += p * __bfloat162float(v[((long long)(b*kv_heads+kvh)*S+j)*D+d]);
                }
                out[((long long)(b*H+h)*S+i)*D+d] = __float2bfloat16(acc);
            }
        }
    }
}

int main(int argc, char** argv) {
    int B = 1, H = 1, S = 64, causal = 0;
