    cudaMemcpy(d_q, qh.data(), qn*2, cudaMemcpyHostToDevice);
    cudaMemcpy(d_k, kh.data(), qn*2, cudaMemcpyHostToDevice);
    cudaMemcpy(d_v, vh.data(), qn*2, cudaMemcpyHostToDevice);
    cudaFuncSetAttribute(attention_fwd_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
    dim3 grid((S + BLOCK_M - 1)/BLOCK_M, B*H);
    float scale = 1.f / sqrtf((float)D);
    attention_fwd_kernel<<<grid, NUM_THREADS, SMEM_BYTES>>>(d_q, d_k, d_v, d_o, S, scale, causal!=0, H, kv_heads);
